('g5_1_sci_u1_L01_basic#2','sci',5,1,'u1','L01','g5_1_sci_u1_L01_basic','lesson_basic','SC5-1-u1-C2',1,'mc','auto','찾아낸 블록에 묻은 흙은 무엇으로 털어 내나요?',ARRAY['SC5-1-u1-X02','SC5-1-u1-X01']::text[],false,'{"seq":2,"concept":"SC5-1-u1-C2","difficulty":1,"kind":"mc","stem":"찾아낸 블록에 묻은 흙은 무엇으로 털어 내나요?","options":[{"t":"작은 붓","correct":true},{"t":"끌 끝","mis":"SC5-1-u1-X02"},{"t":"젖은 수세미","mis":"SC5-1-u1-X01"},{"t":"입김","mis":"SC5-1-u1-X01"}],"explanation":["마지막 단계예요.","살살 털어 내요.","작은 붓이에요."]}'::jsonb),
('g5_1_sci_u1_L01_basic#3','sci',5,1,'u1','L01','g5_1_sci_u1_L01_basic','lesson_basic','SC5-1-u1-C2',1,'ox','auto','흙을 만진 손으로 눈이나 얼굴을 만지지 않아요.',ARRAY['SC5-1-u1-X03']::text[],false,'{"seq":3,"concept":"SC5-1-u1-C2","difficulty":1,"kind":"ox","stem":"흙을 만진 손으로 눈이나 얼굴을 만지지 않아요.","answer":"O","reason_options":[{"t":"흙이 눈에 들어가거나 얼굴이 더러워질 수 있기 때문에","correct":true},{"t":"흙은 깨끗해서 상관없지만 규칙이라서","mis":"SC5-1-u1-X03"}],"mis":"SC5-1-u1-X03","explanation":["안전을 떠올려요.","흙이 눈에 들어갈 수 있어요.","맞는 말이에요."]}'::jsonb),
('g5_1_sci_u1_L01_basic#4','sci',5,1,'u1','L01','g5_1_sci_u1_L01_basic','lesson_basic','SC5-1-u1-C3',1,'sa','auto','「옛날에 살았던 생물의 몸체나 흔적이 땅속에 남은 것을 □□이라고 합니다.」 □□에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC5-1-u1-C3","difficulty":1,"kind":"sa","stem":"「옛날에 살았던 생물의 몸체나 흔적이 땅속에 남은 것을 □□이라고 합니다.」 □□에 알맞은 말을 쓰세요.","answer":["화석"],"explanation":["공룡 뼈를 떠올려요.","땅속에서 나와요.","화석이에요."],"mis":"SC5-1-u1-X04"}'::jsonb),
('g5_1_sci_u1_L01_basic#5','sci',5,1,'u1','L01','g5_1_sci_u1_L01_basic','lesson_basic','SC5-1-u1-C2',2,'match','auto','도구와 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC5-1-u1-C2","difficulty":2,"kind":"match","stem":"도구와 하는 일을 알맞게 이으세요.","pairs":[{"l":"플라스틱 끌","r":"굳은 흙을 조금씩 파낸다"},{"l":"작은 붓","r":"묻은 흙을 털어 낸다"},{"l":"숟가락","r":"흙과 물을 섞는다"},{"l":"보안경","r":"튀는 흙에서 눈을 보호한다"}],"mis":"SC5-1-u1-X02","explanation":["도구를 하나씩 떠올려요.","파내기·털기·섞기·보호예요.","네 가지가 달라요."]}'::jsonb),
('g5_1_sci_u1_L01_basic#6','sci',5,1,'u1','L01','g5_1_sci_u1_L01_basic','lesson_basic','SC5-1-u1-C1',2,'mc','auto','숨겨진 블록을 찾는 활동에서 블록을 숨긴 다음 할 일은 어느 것인가요?',ARRAY['SC5-1-u1-X01']::text[],false,'{"seq":6,"concept":"SC5-1-u1-C1","difficulty":2,"kind":"mc","stem":"숨겨진 블록을 찾는 활동에서 블록을 숨긴 다음 할 일은 어느 것인가요?","options":[{"t":"흙이 단단해지도록 윗부분을 누른다","correct":true},{"t":"흙을 바닥에 쏟아 블록을 바로 꺼낸다","mis":"SC5-1-u1-X01"},{"t":"블록이 잘 보이게 위에 올려 둔다","mis":"SC5-1-u1-X01"},{"t":"그릇에 물을 가득 부어 흙을 씻어 낸다","mis":"SC5-1-u1-X01"}],"explanation":["보이지 않게 숨겼어요.","흙을 단단하게 해요.","윗부분을 눌러요."],"asset":{"type":"passage","lines":["① 투명한 그릇에 흙을 담고 물을 조금씩 넣으며 숟가락으로 섞는다.","② 흙이 뭉치면 작은 블록 몇 개를 보이지 않게 숨기고 윗부분을 누른다.","③ 그릇을 친구와 바꾸어 끌과 작은 붓으로 숨긴 블록을 찾는다.","④ 찾은 블록에 묻은 흙을 작은 붓으로 살살 털어 낸다."],"title":"숨겨진 블록을 찾아라!"}}'::jsonb),
('g5_1_sci_u1_L01_basic#7','sci',5,1,'u1','L01','g5_1_sci_u1_L01_basic','lesson_basic','SC5-1-u1-C1',2,'ox','auto','블록을 찾을 때는 빨리 찾으려고 흙덩이를 바닥에 내리쳐도 돼요.',ARRAY['SC5-1-u1-X01']::text[],false,'{"seq":7,"concept":"SC5-1-u1-C1","difficulty":2,"kind":"ox","stem":"블록을 찾을 때는 빨리 찾으려고 흙덩이를 바닥에 내리쳐도 돼요.","answer":"X","reason_options":[{"t":"서두르면 안에 있는 것이 깨지거나 부서질 수 있기 때문에","correct":true},{"t":"흙덩이를 내리치면 블록이 더 잘 보이기 때문에","mis":"SC5-1-u1-X01"}],"mis":"SC5-1-u1-X01","explanation":["발굴은 어떻게 하나요?","조심스럽게 조금씩 해요.","내리치지 않아요."]}'::jsonb),
