('g5_1_sci_u1_L07_basic#2','sci',5,1,'u1','L07','g5_1_sci_u1_L07_basic','lesson_basic','SC5-1-u1-C21',1,'mc','auto','공룡 발자국 화석으로 알 수 있는 것은 어느 것인가요?',ARRAY['SC5-1-u1-X35']::text[],false,'{"seq":2,"concept":"SC5-1-u1-C21","difficulty":1,"kind":"mc","stem":"공룡 발자국 화석으로 알 수 있는 것은 어느 것인가요?","options":[{"t":"공룡의 크기나 움직임","correct":true},{"t":"공룡의 몸 색깔","mis":"SC5-1-u1-X35"},{"t":"공룡의 울음소리","mis":"SC5-1-u1-X35"},{"t":"공룡이 태어난 날짜","mis":"SC5-1-u1-X35"}],"explanation":["발자국에 남은 것을 봐요.","크기와 간격이에요.","크기나 움직임이에요."]}'::jsonb),
('g5_1_sci_u1_L07_basic#3','sci',5,1,'u1','L07','g5_1_sci_u1_L07_basic','lesson_basic','SC5-1-u1-C23',1,'ox','auto','화석이 많이 발견되는 곳을 화석 산지라고 해요.',ARRAY['SC5-1-u1-X38']::text[],false,'{"seq":3,"concept":"SC5-1-u1-C23","difficulty":1,"kind":"ox","stem":"화석이 많이 발견되는 곳을 화석 산지라고 해요.","answer":"O","reason_options":[{"t":"화석이 많이 나오는 곳이어서 그렇게 부르기 때문에","correct":true},{"t":"화석을 만들어 파는 곳이어서 그렇게 부르기 때문에","mis":"SC5-1-u1-X38"}],"mis":"SC5-1-u1-X38","explanation":["이름을 풀어 봐요.","화석이 나오는 땅이에요.","맞는 말이에요."]}'::jsonb),
