('g5_1_sci_u2_review_b#21','sci',5,1,'u2','','g5_1_sci_u2_review_b','unit_review','SC5-1-u2-C24',3,'mc','auto','라이파이와 빛의 직진을 이어 바르게 말한 것은 어느 것인가요?',ARRAY['SC5-1-u2-X13','SC5-1-u2-X36','SC5-1-u2-X35']::text[],false,'{"seq":21,"concept":"SC5-1-u2-C24","difficulty":3,"kind":"mc","stem":"라이파이와 빛의 직진을 이어 바르게 말한 것은 어느 것인가요?","options":[{"t":"빛이 곧게 나아가 기기에 닿아야 하므로 장애물이 있으면 끊길 수 있다","correct":true},{"t":"빛이 장애물을 돌아가므로 끊기지 않는다","mis":"SC5-1-u2-X13"},{"t":"빛이 없어도 되므로 장애물은 상관없다","mis":"SC5-1-u2-X36"},{"t":"라이파이는 소리로 통신하므로 직진과 관계없다","mis":"SC5-1-u2-X35"}],"explanation":["빛은 곧게 가요.","막히면 못 가요.","첫 번째예요."]}'::jsonb),
('g5_1_sci_u2_review_b#22','sci',5,1,'u2','','g5_1_sci_u2_review_b','unit_review','SC5-1-u2-C8',3,'mc','auto','빛이 없는 세상을 역할놀이로 나타낼 때 가장 알맞은 장면은 어느 것인가요?',ARRAY['SC5-1-u2-X10']::text[],false,'{"seq":22,"concept":"SC5-1-u2-C8","difficulty":3,"kind":"mc","stem":"빛이 없는 세상을 역할놀이로 나타낼 때 가장 알맞은 장면은 어느 것인가요?","options":[{"t":"깜깜한 방에서 더듬더듬 방문을 찾는 장면","correct":true},{"t":"친구의 목소리가 하나도 안 들리는 장면","mis":"SC5-1-u2-X10"},{"t":"꽃향기가 하나도 안 나는 장면","mis":"SC5-1-u2-X10"},{"t":"음식의 맛이 하나도 안 나는 장면","mis":"SC5-1-u2-X10"}],"explanation":["빛이 없으면 무엇을 못 하나요?","보는 일이에요.","방문을 찾는 장면이에요."]}'::jsonb),
('g5_1_sci_u2_review_b#23','sci',5,1,'u2','','g5_1_sci_u2_review_b','unit_review','SC5-1-u2-C16',4,'mc','auto','간이 프로젝터 상자에 끼울 렌즈로 하늘빛반 일지 ⑤의 ㉮와 ㉯ 가운데 알맞은 것과 그 까닭은 어느 것인가요?',ARRAY['SC5-1-u2-X21','SC5-1-u2-X31','SC5-1-u2-X25']::text[],false,'{"seq":23,"concept":"SC5-1-u2-C16","difficulty":4,"kind":"mc","stem":"간이 프로젝터 상자에 끼울 렌즈로 하늘빛반 일지 ⑤의 ㉮와 ㉯ 가운데 알맞은 것과 그 까닭은 어느 것인가요?","options":[{"t":"㉮ — 볼록 렌즈가 빛을 굴절시켜 화면을 크게 비추기 때문에","correct":true},{"t":"㉯ — 빛을 안쪽으로 모으기 때문에","mis":"SC5-1-u2-X21"},{"t":"㉮ — 빛을 반사해 화면을 되비추기 때문에","mis":"SC5-1-u2-X31"},{"t":"둘 다 아니다 — 렌즈는 빛을 꺾지 않기 때문에","mis":"SC5-1-u2-X25"}],"explanation":["간이 프로젝터를 떠올려요.","볼록 렌즈를 끼웠어요.","㉮예요."],"asset":{"type":"passage","lines":["렌즈 ㉮ — 가운데가 볼록하다. 지난 빛이 안쪽으로 꺾여 모였다.","렌즈 ㉯ — 가운데가 오목하다. 지난 빛이 바깥쪽으로 꺾여 퍼졌다.","물이 든 통 — 공기에서 물로 비스듬히 비추니 경계에서 꺾였다.","물을 뺀 통 — 같은 자리에서 비추니 곧게 나아갔다."],"title":"하늘빛반 빛 탐구 일지 ⑤ 렌즈와 물에 비춘 빛"}}'::jsonb),
('g5_1_sci_u2_review_b#24','sci',5,1,'u2','','g5_1_sci_u2_review_b','unit_review','SC5-1-u2-C9',4,'essay','teacher','하늘빛반 일지 ③의 ①~③에서 알 수 있는 빛의 성질을 쓰고, ④에서 그림자가 두 개 생긴 까닭을 그 성질과 이어서 설명하세요.','{}'::text[],false,'{"seq":24,"concept":"SC5-1-u2-C9","difficulty":4,"kind":"essay","stem":"하늘빛반 일지 ③의 ①~③에서 알 수 있는 빛의 성질을 쓰고, ④에서 그림자가 두 개 생긴 까닭을 그 성질과 이어서 설명하세요.","answer_guide":{"answer":"예: ①~③에서 햇빛과 레이저 지시기의 빛이 곧게 나아가는 것을 보아 빛은 곧게 나아간다는 것을 알 수 있다. 이것을 빛의 직진이라고 한다. ④에서는 두 손전등의 빛이 각각 곧게 나아가다가 불투명한 인형에 막혀 더 나아가지 못했기 때문에 인형 뒤 벽에 그림자가 두 개 생겼다.","scoring_points":["빛의 직진을 썼는가","불투명한 물체에 막힌다고 썼는가","두 빛이 각각 막힌다고 썼는가"]},"explanation":["곧은 빛을 떠올려요.","막힌 뒤쪽이에요.","두 개의 까닭을 써요."],"asset":{"type":"passage","lines":["① 구멍 뚫린 도화지 아래 도화지에 동그란 햇빛이 비쳤다.","② 아래 도화지를 수직으로 세우니 햇빛이 곧게 뻗어 보였다.","③ 어두운 교실에서 레이저 지시기 앞에 물을 뿌리니 곧은 줄이 보였다.","④ 손전등 두 개로 인형을 비추니 벽에 그림자가 두 개 생겼다."],"title":"하늘빛반 빛 탐구 일지 ③ 빛이 나아가는 모습"}}'::jsonb),
('g5_1_sci_u2_review_b#25','sci',5,1,'u2','','g5_1_sci_u2_review_b','unit_review','SC5-1-u2-C19',4,'essay','teacher','하늘빛반 일지 ⑧의 도하와 은결의 말이 왜 옳지 않은지 바로잡아 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC5-1-u2-C19","difficulty":4,"kind":"essay","stem":"하늘빛반 일지 ⑧의 도하와 은결의 말이 왜 옳지 않은지 바로잡아 쓰세요.","answer_guide":{"answer":"예: 도하야, 렌즈는 빛을 반사하는 것이 아니라 굴절시켜서 글씨를 크게 보여 줘. 빛을 반사하는 것은 거울이야. 은결아, 거울과 렌즈는 빛이 나아가는 방향을 바꾸거나 꺾을 뿐이야. 거울과 렌즈가 모두 사라져도 빛은 곧게 나아가고, 햇빛이 있으면 물체도 볼 수 있어. 다만 뒷거울로 뒤차를 보거나 돋보기로 글씨를 크게 보는 일이 어려워질 거야.","scoring_points":["도하의 말을 굴절로 바로잡았는가","은결의 말을 빛 자체는 그대로라고 바로잡았는가","거울·렌즈가 없을 때 어려워지는 일을 썼는가"]},"explanation":["도하부터 따져요.","은결은 빛 자체예요.","근거를 들어요."],"asset":{"type":"passage","lines":["보미 — 「눈에서 빛이 나와서 물체가 보이는 거야.」","찬희 — 「물을 뿌려야만 빛이 곧게 나아가.」","도하 — 「렌즈는 빛을 반사해서 글씨를 크게 보여 줘.」","은결 — 「거울과 렌즈가 모두 사라지면 빛도 곧게 못 나아가.」","시후 — 「라이파이는 빛이 없어도 잘 돼.」"],"title":"하늘빛반 빛 탐구 일지 ⑧ 교실 토론"}}'::jsonb),
