('g5_1_sci_u2_review_d#10','sci',5,1,'u2','','g5_1_sci_u2_review_d','unit_review','SC5-1-u2-C7',2,'mc','auto','하늘빛반 일지 ②의 ④에서 커튼 틈 쪽 책만 보인 까닭은 어느 것인가요?',ARRAY['SC5-1-u2-X07','SC5-1-u2-X09']::text[],false,'{"seq":10,"concept":"SC5-1-u2-C7","difficulty":2,"kind":"mc","stem":"하늘빛반 일지 ②의 ④에서 커튼 틈 쪽 책만 보인 까닭은 어느 것인가요?","options":[{"t":"커튼 틈으로 들어온 햇빛이 그쪽 책을 비추었기 때문에","correct":true},{"t":"그쪽 책이 스스로 빛을 냈기 때문에","mis":"SC5-1-u2-X07"},{"t":"그쪽 책이 더 컸기 때문에","mis":"SC5-1-u2-X09"},{"t":"그쪽이 더 따뜻했기 때문에","mis":"SC5-1-u2-X09"}],"explanation":["빛이 어디로 들어왔나요?","커튼 틈이에요.","햇빛이 비췄어요."],"asset":{"type":"passage","lines":["① 어둠상자 구멍을 손전등으로 빈틈없이 막고 관찰 — 잘 보이지 않음","② 손전등을 켜고 관찰 — 상자 속 인형이 잘 보임","③ 짝과 역할을 바꾸어 한 번 더 함","④ 낮, 커튼을 모두 치고 불을 끔 — 커튼 틈 쪽 책만 보임","⑤ 밤, 가로등 아래 자전거는 보이고 골목 안 자전거는 안 보임"],"title":"하늘빛반 빛 탐구 일지 ② 물체를 보려면"}}'::jsonb),
('g5_1_sci_u2_review_d#11','sci',5,1,'u2','','g5_1_sci_u2_review_d','unit_review','SC5-1-u2-C11',2,'mc','auto','하늘빛반 일지 ③의 ④에서 손전등 하나를 끄면 어떻게 될까요?',ARRAY['SC5-1-u2-X15','SC5-1-u2-X13']::text[],false,'{"seq":11,"concept":"SC5-1-u2-C11","difficulty":2,"kind":"mc","stem":"하늘빛반 일지 ③의 ④에서 손전등 하나를 끄면 어떻게 될까요?","options":[{"t":"그림자가 하나만 남는다","correct":true},{"t":"그림자 두 개가 그대로 있다","mis":"SC5-1-u2-X15"},{"t":"그림자가 셋으로 늘어난다","mis":"SC5-1-u2-X15"},{"t":"빛이 인형을 돌아가 그림자가 모두 사라진다","mis":"SC5-1-u2-X13"}],"explanation":["빛이 하나 줄었어요.","막히는 빛도 하나예요.","하나만 남아요."],"asset":{"type":"passage","lines":["① 구멍 뚫린 도화지 아래 도화지에 동그란 햇빛이 비쳤다.","② 아래 도화지를 수직으로 세우니 햇빛이 곧게 뻗어 보였다.","③ 어두운 교실에서 레이저 지시기 앞에 물을 뿌리니 곧은 줄이 보였다.","④ 손전등 두 개로 인형을 비추니 벽에 그림자가 두 개 생겼다."],"title":"하늘빛반 빛 탐구 일지 ③ 빛이 나아가는 모습"}}'::jsonb),
('g5_1_sci_u2_review_d#12','sci',5,1,'u2','','g5_1_sci_u2_review_d','unit_review','SC5-1-u2-C13',2,'mc','auto','하늘빛반 일지 ④의 ④를 보고 고칠 점으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u2-X18','SC5-1-u2-X17']::text[],false,'{"seq":12,"concept":"SC5-1-u2-C13","difficulty":2,"kind":"mc","stem":"하늘빛반 일지 ④의 ④를 보고 고칠 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"교실을 어둡게 하고 실험한다","correct":true},{"t":"레이저 지시기의 빛을 더 세게 한다","mis":"SC5-1-u2-X18"},{"t":"거울을 치우고 실험한다","mis":"SC5-1-u2-X17"},{"t":"교실 불을 더 밝게 켠다","mis":"SC5-1-u2-X18"}],"explanation":["빛의 길이 안 보였어요.","밝으면 잘 안 보여요.","어둡게 해요."],"asset":{"type":"passage","lines":["① 레이저 지시기를 거울에 비추니 빛이 방향을 바꾸어 모양판 가에 닿았다.","② 레이저 지시기는 그대로 두고 거울을 조금 돌리니 모양판 나에 닿았다.","③ 거울을 치우니 빛이 곧게 나아가 벽에 닿았다.","④ 교실 불을 켜자 빛이 지나가는 길이 잘 보이지 않았다."],"title":"하늘빛반 빛 탐구 일지 ④ 거울에 비춘 빛"}}'::jsonb),
('g5_1_sci_u2_review_d#13','sci',5,1,'u2','','g5_1_sci_u2_review_d','unit_review','SC5-1-u2-C18',2,'mc','auto','하늘빛반 일지 ⑤에서 물이 든 통과 물을 뺀 통을 견주어 알 수 있는 것은 어느 것인가요?',ARRAY['SC5-1-u2-X25','SC5-1-u2-X22']::text[],false,'{"seq":13,"concept":"SC5-1-u2-C18","difficulty":2,"kind":"mc","stem":"하늘빛반 일지 ⑤에서 물이 든 통과 물을 뺀 통을 견주어 알 수 있는 것은 어느 것인가요?","options":[{"t":"빛은 서로 다른 물질의 경계를 지날 때 꺾인다","correct":true},{"t":"빛은 언제나 꺾여 나아간다","mis":"SC5-1-u2-X25"},{"t":"물을 빼도 빛은 꺾인다","mis":"SC5-1-u2-X25"},{"t":"빛은 물속에서 사라진다","mis":"SC5-1-u2-X22"}],"explanation":["물만 달라졌어요.","경계가 있고 없어요.","경계에서 꺾여요."],"asset":{"type":"passage","lines":["렌즈 ㉮ — 가운데가 볼록하다. 지난 빛이 안쪽으로 꺾여 모였다.","렌즈 ㉯ — 가운데가 오목하다. 지난 빛이 바깥쪽으로 꺾여 퍼졌다.","물이 든 통 — 공기에서 물로 비스듬히 비추니 경계에서 꺾였다.","물을 뺀 통 — 같은 자리에서 비추니 곧게 나아갔다."],"title":"하늘빛반 빛 탐구 일지 ⑤ 렌즈와 물에 비춘 빛"}}'::jsonb),
