('g5_1_sci_u2_review_d#17','sci',5,1,'u2','','g5_1_sci_u2_review_d','unit_review','SC5-1-u2-C18',3,'error','auto','하늘빛반 일지 ⑧에서 은결의 말을 바르게 고친 친구는 누구인가요?',ARRAY['SC5-1-u2-X40','SC5-1-u2-X28']::text[],false,'{"seq":17,"concept":"SC5-1-u2-C18","difficulty":3,"kind":"error","stem":"하늘빛반 일지 ⑧에서 은결의 말을 바르게 고친 친구는 누구인가요?","options":[{"t":"태린 — 「거울과 렌즈가 없어도 빛은 곧게 나아가고, 빛이 있으면 물체도 보여.」","correct":true,"mis_target":"SC5-1-u2-X40"},{"t":"소윤 — 「거울과 렌즈가 사라지면 낮에도 아무것도 안 보여.」","mis":"SC5-1-u2-X40"},{"t":"현서 — 「거울이 빛을 만들어 주니까 빛도 사라져.」","mis":"SC5-1-u2-X28"}],"explanation":["빛 자체를 떠올려요.","거울과 렌즈는 빛을 바꿀 뿐이에요.","태린이 바르게 고쳤어요."],"asset":{"type":"passage","lines":["보미 — 「눈에서 빛이 나와서 물체가 보이는 거야.」","찬희 — 「물을 뿌려야만 빛이 곧게 나아가.」","도하 — 「렌즈는 빛을 반사해서 글씨를 크게 보여 줘.」","은결 — 「거울과 렌즈가 모두 사라지면 빛도 곧게 못 나아가.」","시후 — 「라이파이는 빛이 없어도 잘 돼.」"],"title":"하늘빛반 빛 탐구 일지 ⑧ 교실 토론"}}'::jsonb),
('g5_1_sci_u2_review_d#18','sci',5,1,'u2','','g5_1_sci_u2_review_d','unit_review','SC5-1-u2-C12',3,'ox','auto','반사와 굴절은 모두 곧게 나아가던 빛이 무언가를 만나 나아가는 방향이 달라지는 현상이에요.',ARRAY['SC5-1-u2-X16']::text[],false,'{"seq":18,"concept":"SC5-1-u2-C12","difficulty":3,"kind":"ox","stem":"반사와 굴절은 모두 곧게 나아가던 빛이 무언가를 만나 나아가는 방향이 달라지는 현상이에요.","answer":"O","reason_options":[{"t":"반사는 거울에 부딪쳐, 굴절은 경계에서 방향이 달라지기 때문에","correct":true},{"t":"반사와 굴절은 모두 빛이 사라지는 현상이기 때문에","mis":"SC5-1-u2-X16"}],"mis":"SC5-1-u2-X16","explanation":["두 성질을 견줘요.","방향이 달라져요.","맞는 말이에요."]}'::jsonb),
('g5_1_sci_u2_review_d#19','sci',5,1,'u2','','g5_1_sci_u2_review_d','unit_review','SC5-1-u2-C14',3,'mc','auto','밤에 가로등 빛이 방으로 들어오는 것을 빛의 반사를 이용해 막는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u2-X23','SC5-1-u2-X19']::text[],false,'{"seq":19,"concept":"SC5-1-u2-C14","difficulty":3,"kind":"mc","stem":"밤에 가로등 빛이 방으로 들어오는 것을 빛의 반사를 이용해 막는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"창문 바깥쪽에 거울을 달아 빛을 다른 쪽으로 되비춘다","correct":true},{"t":"창문에 볼록 렌즈를 붙여 빛을 크게 만든다","mis":"SC5-1-u2-X23"},{"t":"가로등을 더 밝게 켜 둔다","mis":"SC5-1-u2-X19"},{"t":"창문을 활짝 열어 둔다","mis":"SC5-1-u2-X19"}],"explanation":["반사를 이용해요.","거울이 필요해요.","되비춰요."]}'::jsonb),
('g5_1_sci_u2_review_d#20','sci',5,1,'u2','','g5_1_sci_u2_review_d','unit_review','SC5-1-u2-C13',3,'mc','auto','그림에서 레이저 지시기의 빛으로 모양판 다를 맞히려면 어떻게 하면 될까요?',ARRAY['SC5-1-u2-X17','SC5-1-u2-X18']::text[],false,'{"seq":20,"concept":"SC5-1-u2-C13","difficulty":3,"kind":"mc","stem":"그림에서 레이저 지시기의 빛으로 모양판 다를 맞히려면 어떻게 하면 될까요?","options":[{"t":"레이저 지시기는 그대로 두고 거울의 방향을 조금 바꾼다","correct":true},{"t":"거울을 치운다","mis":"SC5-1-u2-X17"},{"t":"레이저 지시기의 빛을 더 세게 한다","mis":"SC5-1-u2-X18"},{"t":"교실을 더 밝게 한다","mis":"SC5-1-u2-X18"}],"explanation":["지금은 나에 닿아요.","거울 방향이 열쇠예요.","조금 바꿔요."],"asset":{"type":"geo","items":[{"w":300,"h":205,"seg":[[[260,15],[260,185]],[[40,40],[260,100]],[[260,100],[40,160]]],"lab":[[[80,24],"레이저 지시기"],[[238,196],"평면거울"],[[22,100],"가"],[[22,160],"나"],[[22,190],"다"]],"cap":"평면거울로 모양판 맞히기"}],"tag":false}}'::jsonb),
('g5_1_sci_u2_review_d#21','sci',5,1,'u2','','g5_1_sci_u2_review_d','unit_review','SC5-1-u2-C25',3,'mc','auto','라이파이의 좋은 점과 아쉬운 점을 바르게 나눈 것은 어느 것인가요?',ARRAY['SC5-1-u2-X39','SC5-1-u2-X36','SC5-1-u2-X37']::text[],false,'{"seq":21,"concept":"SC5-1-u2-C25","difficulty":3,"kind":"mc","stem":"라이파이의 좋은 점과 아쉬운 점을 바르게 나눈 것은 어느 것인가요?","options":[{"t":"좋은 점: 빛을 가리면 보안에 유리 — 아쉬운 점: 장애물이 있으면 끊김","correct":true},{"t":"좋은 점: 장애물이 있으면 끊김 — 아쉬운 점: 보안에 유리","mis":"SC5-1-u2-X39"},{"t":"좋은 점: 빛이 없어도 잘 됨 — 아쉬운 점: 없음","mis":"SC5-1-u2-X36"},{"t":"좋은 점: 빛이 벽을 뚫음 — 아쉬운 점: LED 등을 씀","mis":"SC5-1-u2-X37"}],"explanation":["좋은 점과 아쉬운 점이에요.","보안과 장애물이에요.","첫 번째예요."]}'::jsonb),
('g5_1_sci_u2_review_d#22','sci',5,1,'u2','','g5_1_sci_u2_review_d','unit_review','SC5-1-u2-C21',3,'mc','auto','발표 자료에 다른 모둠이 그린 그림을 쓰고 싶어요. 가장 알맞은 방법은 어느 것인가요?',ARRAY['SC5-1-u2-X29']::text[],false,'{"seq":22,"concept":"SC5-1-u2-C21","difficulty":3,"kind":"mc","stem":"발표 자료에 다른 모둠이 그린 그림을 쓰고 싶어요. 가장 알맞은 방법은 어느 것인가요?","options":[{"t":"그린 친구에게 허락을 받고 누구의 그림인지 밝힌다","correct":true},{"t":"말없이 가져다 쓴다","mis":"SC5-1-u2-X29"},{"t":"조금 바꿔서 내가 그린 것처럼 쓴다","mis":"SC5-1-u2-X29"},{"t":"그림은 창작물이 아니니 마음대로 쓴다","mis":"SC5-1-u2-X29"}],"explanation":["다른 사람의 창작물이에요.","허락이 필요해요.","첫 번째예요."]}'::jsonb),
('g5_1_sci_u2_review_d#23','sci',5,1,'u2','','g5_1_sci_u2_review_d','unit_review','SC5-1-u2-C25',4,'mc','auto','학교 도서관에 라이파이를 쓰려고 할 때 가장 알맞은 계획은 어느 것인가요?',ARRAY['SC5-1-u2-X37','SC5-1-u2-X36']::text[],false,'{"seq":23,"concept":"SC5-1-u2-C25","difficulty":4,"kind":"mc","stem":"학교 도서관에 라이파이를 쓰려고 할 때 가장 알맞은 계획은 어느 것인가요?","options":[{"t":"책상마다 LED 등의 빛이 닿는지 확인하고 빛을 가리는 높은 책장을 옮긴다","correct":true},{"t":"보안을 위해 LED 등을 모두 끈다","mis":"SC5-1-u2-X37"},{"t":"빛이 없어도 되니 지하 창고에 둔다","mis":"SC5-1-u2-X36"},{"t":"벽이 많을수록 빨라지니 칸막이를 세운다","mis":"SC5-1-u2-X36"}],"explanation":["빛이 닿아야 해요.","가리는 것을 줄여요.","첫 번째예요."]}'::jsonb),
('g5_1_sci_u2_review_d#24','sci',5,1,'u2','','g5_1_sci_u2_review_d','unit_review','SC5-1-u2-C18',4,'essay','teacher','하늘빛반 일지 ⑤의 네 관찰을 이용하여 빛의 굴절을 설명하고, 볼록 렌즈와 오목 렌즈를 지난 빛이 어떻게 다른지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SC5-1-u2-C18","difficulty":4,"kind":"essay","stem":"하늘빛반 일지 ⑤의 네 관찰을 이용하여 빛의 굴절을 설명하고, 볼록 렌즈와 오목 렌즈를 지난 빛이 어떻게 다른지 쓰세요.","answer_guide":{"answer":"예: 빛이 직진하다가 렌즈를 통과하거나 공기에서 물로 비스듬히 들어갈 때 나아가는 방향이 꺾인다. 물을 빼면 꺾이지 않으므로 빛은 서로 다른 물질의 경계에서 꺾인다는 것을 알 수 있다. 이것을 빛의 굴절이라고 한다. 볼록 렌즈를 지난 빛은 안쪽으로 꺾여 모이고, 오목 렌즈를 지난 빛은 바깥쪽으로 꺾여 퍼진다.","scoring_points":["굴절을 경계에서 꺾임으로 설명했는가","물을 뺀 통과 견주었는가","볼록·오목 렌즈의 차이를 썼는가"]},"explanation":["네 관찰을 견줘요.","경계가 열쇠예요.","두 렌즈를 견줘요."],"asset":{"type":"passage","lines":["렌즈 ㉮ — 가운데가 볼록하다. 지난 빛이 안쪽으로 꺾여 모였다.","렌즈 ㉯ — 가운데가 오목하다. 지난 빛이 바깥쪽으로 꺾여 퍼졌다.","물이 든 통 — 공기에서 물로 비스듬히 비추니 경계에서 꺾였다.","물을 뺀 통 — 같은 자리에서 비추니 곧게 나아갔다."],"title":"하늘빛반 빛 탐구 일지 ⑤ 렌즈와 물에 비춘 빛"}}'::jsonb),
('g5_1_sci_u2_review_d#25','sci',5,1,'u2','','g5_1_sci_u2_review_d','unit_review','SC5-1-u2-C26',4,'essay','teacher','「빛의 성질」 단원에서 배운 것을 「물체를 보려면 → 빛의 세 가지 성질 → 거울과 렌즈 → 빛으로 통신하는 기술」의 차례로 정리해 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC5-1-u2-C26","difficulty":4,"kind":"essay","stem":"「빛의 성질」 단원에서 배운 것을 「물체를 보려면 → 빛의 세 가지 성질 → 거울과 렌즈 → 빛으로 통신하는 기술」의 차례로 정리해 쓰세요.","answer_guide":{"answer":"예: 물체를 보려면 물체를 비추는 빛이 있어야 한다. 빛은 곧게 나아가고(직진), 거울에 부딪치면 나아가는 방향이 바뀌며(반사), 서로 다른 물질의 경계에서 꺾여 나아간다(굴절). 거울은 반사를 이용해 치과 거울·자동차 뒷거울로, 렌즈는 굴절을 이용해 돋보기안경·사진기로 우리 생활을 편리하게 한다. 라이파이는 LED 등의 빛으로 통신하는 기술이며, 이런 기술을 연구하려면 빛의 성질을 알아야 한다.","scoring_points":["물체를 보려면 빛이 필요함을 썼는가","직진·반사·굴절을 바르게 썼는가","거울·렌즈의 쓰임과 라이파이를 썼는가"]},"explanation":["처음부터 떠올려요.","세 성질을 넣어요.","쓰임과 기술로 마무리해요."]}'::jsonb)
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES 
('SC5-1-u3-C1','sci',5,1,'u3',1,'물질의 변신 — 거품 목욕제·발포 바이타민처럼 물에 넣으면 거품을 내며 녹는 물질, 고체 치약처럼 천천히 풀어지는 물질이 있음 · 물질마다 물에서 변하는 모습이 서로 다름 · 직접 넣어 보기 전에는 알기 어려움',ARRAY['여러 가지 물질이 물에 녹는 현상을 관찰하여 용해와 용액을 설명하고, 용해 전후의 무게를 비교(문구 초안 — 성취기준 코드 W7 확인)']::text[],1),
('SC5-1-u3-C2','sci',5,1,'u3',1,'촬영 활동 — 모둠별로 물질 한 가지 고르기 → 빵 끈으로 묶어 나무 막대에 연결(물속 한자리에 두고 잘 보려고) → 물이 담긴 비커에 넣기 → 변하는 모습을 스마트 기기로 동영상 촬영(변하는 순간은 금방 지나가므로 처음부터) → 편집해 제목과 자막을 넣고 함께 보며 이야기',ARRAY['여러 가지 물질이 물에 녹는 현상을 관찰하여 용해와 용액을 설명하고, 용해 전후의 무게를 비교(문구 초안 — 성취기준 코드 W7 확인)']::text[],2),
('SC5-1-u3-C3','sci',5,1,'u3',1,'실험 안전 — 실험복·보안경·실험용 장갑을 갖춤 · 유리 기구가 깨지지 않도록 조심 · 실험에 사용하는 물질은 맛보지 않음 · 끝나면 주변을 깨끗이 정리하고 폐기물을 올바르게 처리',ARRAY['여러 가지 물질이 물에 녹는 현상을 관찰하여 용해와 용액을 설명하고, 용해 전후의 무게를 비교(문구 초안 — 성취기준 코드 W7 확인)']::text[],3),
('SC5-1-u3-C4','sci',5,1,'u3',2,'세 물질 실험 결과 — 설탕과 가루 바이타민은 물에 녹아 보이지 않게 되고, 탄산 칼슘(석회석 등에서 얻는 흰색 물질)은 녹지 않고 그대로 남음 · 소금은 저으면 보이지 않게 되지만 후춧가루는 저어도 떠다님 · 물에 넣으면 어떤 물질은 녹지만 어떤 물질은 녹지 않음',ARRAY['여러 가지 물질이 물에 녹는 현상을 관찰하여 용해와 용액을 설명하고, 용해 전후의 무게를 비교(문구 초안 — 성취기준 코드 W7 확인)']::text[],4),
('SC5-1-u3-C5','sci',5,1,'u3',2,'네 낱말 — 용해: 어떤 물질이 다른 물질에 녹아 골고루 섞이는 현상(일어나는 일) · 용매: 다른 물질을 녹이는 물질(설탕물의 물) · 용질: 용매에 녹는 물질(설탕물의 설탕) · 용액: 용매와 용질이 골고루 섞여 있는 물질(설탕물)',ARRAY['여러 가지 물질이 물에 녹는 현상을 관찰하여 용해와 용액을 설명하고, 용해 전후의 무게를 비교(문구 초안 — 성취기준 코드 W7 확인)']::text[],5),
('SC5-1-u3-C6','sci',5,1,'u3',2,'용액의 성질 — 색깔이나 맛 등의 성질이 어느 부분이나 일정하고, 오래 두어도 뜨거나 가라앉는 것이 없음 · 설탕물·소금물은 용액 · 흙탕물·후춧가루를 넣은 물은 섞여 있기만 할 뿐 가라앉거나 떠 있는 것이 있어 용액이 아님 · 그냥 섞여 있는 것과 녹아 골고루 섞인 것은 다름',ARRAY['여러 가지 물질이 물에 녹는 현상을 관찰하여 용해와 용액을 설명하고, 용해 전후의 무게를 비교(문구 초안 — 성취기준 코드 W7 확인)']::text[],6),
('SC5-1-u3-C7','sci',5,1,'u3',2,'세 물질 실험 — 결과를 예상 → 유리병 세 개에 물을 같은 양씩(삼분의 이) 넣음 → 설탕·가루 바이타민·탄산 칼슘을 한 숟가락씩 넣음(담는 양을 최대한 같게, 약숟가락을 구분해 써서 섞이지 않게) → 뚜껑을 닫고 흔든 뒤 평평한 곳에서 5분 정도 지나 관찰 → 비교 · 물이 튀지 않게 살살 넣기',ARRAY['여러 가지 물질이 물에 녹는 현상을 관찰하여 용해와 용액을 설명하고, 용해 전후의 무게를 비교(문구 초안 — 성취기준 코드 W7 확인)']::text[],7),
('SC5-1-u3-C8','sci',5,1,'u3',3,'용해되는 과정 — 각설탕(용질)을 물(용매)에 넣으면 크기가 점점 작아지며 녹음 → 눈에 보이지 않을 정도로 작아짐 → 물에 골고루 섞이며 설탕물(용액)이 됨 · 녹아서 보이지 않게 되었을 뿐 없어진 것이 아님',ARRAY['여러 가지 물질이 물에 녹는 현상을 관찰하여 용해와 용액을 설명하고, 용해 전후의 무게를 비교(문구 초안 — 성취기준 코드 W7 확인)']::text[],8),
('SC5-1-u3-C9','sci',5,1,'u3',3,'무게 비교 — 각설탕이 용해되기 전과 용해된 후의 무게는 같음 · 같은 양의 물에 용질을 많이 녹일수록 용액은 더 무거움(분말주스 열 숟가락 > 한 숟가락)',ARRAY['여러 가지 물질이 물에 녹는 현상을 관찰하여 용해와 용액을 설명하고, 용해 전후의 무게를 비교(문구 초안 — 성취기준 코드 W7 확인)']::text[],9),
('SC5-1-u3-C10','sci',5,1,'u3',3,'까닭 — 완전히 용해된 용질은 사라진 것이 아니라 용액 속에 그대로 있음 · 그래서 용해되기 전과 후의 무게가 같음 · 설탕물에서 단맛이 나는 것도 설탕이 그대로 있다는 증거',ARRAY['여러 가지 물질이 물에 녹는 현상을 관찰하여 용해와 용액을 설명하고, 용해 전후의 무게를 비교(문구 초안 — 성취기준 코드 W7 확인)']::text[],10),
('SC5-1-u3-C11','sci',5,1,'u3',3,'무게 실험 — 예상 → 유리병에 물을 절반 정도 넣고 뚜껑을 닫음 → 물이 든 유리병과 각설탕 한 개를 담은 페트리 접시를 전자저울에 함께 올려 잼(용해되기 전) → 핀셋으로 각설탕을 넣고 용해되는 모습 관찰 → 다 용해되면 설탕물이 담긴 유리병과 빈 페트리 접시를 함께 올려 잼(용해된 후) · 탐구 결과는 예상과 달라도 사실대로 기록',ARRAY['여러 가지 물질이 물에 녹는 현상을 관찰하여 용해와 용액을 설명하고, 용해 전후의 무게를 비교(문구 초안 — 성취기준 코드 W7 확인)']::text[],11),
('SC5-1-u3-C12','sci',5,1,'u3',4,'용질의 종류 — 같은 온도, 같은 양의 물에 용해되는 용질의 양은 용질의 종류에 따라 다름 · 설탕은 모두 용해되고, 소금은 일부가 용해되지 않고 바닥에 남으며, 백반(봉숭아 물들이는 데 쓰는 흰색 물질)은 가장 적게 용해됨 · 같은 조건에서 설탕 > 소금 > 백반 · 어떤 용질이든 끝없이 녹지는 않음',ARRAY['용질의 종류와 물의 온도에 따라 용질이 녹는 양을 비교하고, 용액의 진하기를 상대적으로 비교하는 방법을 설명(문구 초안 — 성취기준 코드 W7 확인)']::text[],12),
('SC5-1-u3-C13','sci',5,1,'u3',4,'공정한 비교 — 알아보려는 조건 하나만 다르게 하고 나머지는 모두 같게 해야 결과가 그 조건 때문이라고 말할 수 있음 · 용질의 종류를 비교할 때: 물의 온도(상온)·물의 양(50 mL)·약숟가락에 담는 양·젓는 정도는 같게, 용질의 종류만 다르게',ARRAY['용질의 종류와 물의 온도에 따라 용질이 녹는 양을 비교하고, 용액의 진하기를 상대적으로 비교하는 방법을 설명(문구 초안 — 성취기준 코드 W7 확인)']::text[],13),
('SC5-1-u3-C14','sci',5,1,'u3',4,'실험 방법 — 예상 → 눈금실린더로 비커 세 개에 상온의 물을 50 mL씩 넣음 → 설탕·소금·백반을 한 숟가락씩 넣고 유리 막대로 충분히 저으며 관찰 → 되풀이하며 비교 · 이름 붙임딱지로 비커 표시 · 용질이 바닥에 남으면 더 넣지 않음 · 백반이 피부에 닿지 않게 조심, 맛보지 않기',ARRAY['용질의 종류와 물의 온도에 따라 용질이 녹는 양을 비교하고, 용액의 진하기를 상대적으로 비교하는 방법을 설명(문구 초안 — 성취기준 코드 W7 확인)']::text[],14),
('SC5-1-u3-C15','sci',5,1,'u3',5,'물의 온도 — 같은 용질이라도 물의 온도에 따라 용해되는 양이 다름 · 물의 양이 같을 때 대체로 물의 온도가 높을수록 용질이 더 많이 용해됨(따뜻한 물에서 백반이 더 많이 녹음) · 용해되는 양에 영향을 주는 두 요인 = 용질의 종류와 물의 온도',ARRAY['용질의 종류와 물의 온도에 따라 용질이 녹는 양을 비교하고, 용액의 진하기를 상대적으로 비교하는 방법을 설명(문구 초안 — 성취기준 코드 W7 확인)']::text[],15),
('SC5-1-u3-C16','sci',5,1,'u3',5,'더 녹이기 — 바닥에 남아 있는 용질은 물의 온도를 높여 더 녹일 수 있음 · 분말주스는 찬물보다 따뜻한 물에서 더 잘 녹음 · 옷이나 신발에 가루 세제가 남으면 헹구는 물의 온도를 높임 · 용질을 더 넣거나 물을 차갑게 하면 더 녹지 않음',ARRAY['용질의 종류와 물의 온도에 따라 용질이 녹는 양을 비교하고, 용액의 진하기를 상대적으로 비교하는 방법을 설명(문구 초안 — 성취기준 코드 W7 확인)']::text[],16),
('SC5-1-u3-C17','sci',5,1,'u3',5,'탐구 계획 — 예상 → 다르게 해야 할 조건 정하기(물의 온도 하나: 차가운 물과 따뜻한 물) → 같게 해야 할 조건 정하기(용질의 종류(백반)·물의 양·약숟가락에 담는 양) → 실험 과정 정하기 → 결과를 견주어 탐구 보고서에 적기(탐구 주제·조건·결과·알게 된 점·더 알고 싶은 점) · 다르게 할 조건은 딱 하나',ARRAY['용질의 종류와 물의 온도에 따라 용질이 녹는 양을 비교하고, 용액의 진하기를 상대적으로 비교하는 방법을 설명(문구 초안 — 성취기준 코드 W7 확인)']::text[],17),
('SC5-1-u3-C18','sci',5,1,'u3',6,'용액의 진하기 — 같은 양의 용매에 용해된 용질의 양이 많고 적은 정도 · 두 용액을 견주어 어느 쪽이 더 진한지 말함(상대적) · 용매의 양을 같게 해야 용질의 양만으로 견줄 수 있음',ARRAY['용질의 종류와 물의 온도에 따라 용질이 녹는 양을 비교하고, 용액의 진하기를 상대적으로 비교하는 방법을 설명(문구 초안 — 성취기준 코드 W7 확인)']::text[],18),
('SC5-1-u3-C19','sci',5,1,'u3',6,'진한 용액 — 용매의 양이 같을 때 용질이 많이 녹아 있을수록 진한 용액 · 용질의 양이 같을 때 용매가 적을수록 진한 용액 · 물을 더 넣으면 묽어짐',ARRAY['용질의 종류와 물의 온도에 따라 용질이 녹는 양을 비교하고, 용액의 진하기를 상대적으로 비교하는 방법을 설명(문구 초안 — 성취기준 코드 W7 확인)']::text[],19),
('SC5-1-u3-C20','sci',5,1,'u3',6,'색깔로 비교 — 황설탕 용액은 진할수록 색깔이 더 진함 · 흰 종이를 비커 뒤에 대면 색깔을 더 정확하게 봄 · 백설탕 용액은 색깔이 거의 같아 색깔로는 가리기 어려움',ARRAY['용질의 종류와 물의 온도에 따라 용질이 녹는 양을 비교하고, 용액의 진하기를 상대적으로 비교하는 방법을 설명(문구 초안 — 성취기준 코드 W7 확인)']::text[],20),
('SC5-1-u3-C21','sci',5,1,'u3',6,'뜨는 정도로 비교 — 크기와 무게가 같은 방울토마토를 넣으면 진한 용액일수록 더 높이 떠오름 · 쓴 방울토마토는 핀셋으로 꺼내 수건으로 닦아 다시 씀 · 사해는 소금이 많이 녹아 있어 몸이 쉽게 떠오름 · 디지털 염도계는 진할수록 수치가 커짐 · 떠 있는 메추리알을 낮추려면 물을 더 넣어 묽게 함 · 맛·색깔·뜨는 정도 등으로 비교(실험에서는 맛보지 않음)',ARRAY['용질의 종류와 물의 온도에 따라 용질이 녹는 양을 비교하고, 용액의 진하기를 상대적으로 비교하는 방법을 설명(문구 초안 — 성취기준 코드 W7 확인)']::text[],21),
('SC5-1-u3-C22','sci',5,1,'u3',7,'생활 속 용액 — 손 소독제·손 세정제(세균·오염 물질 제거), 구강 청결제(입안을 청결하게), 식물 영양제(양분이 녹아 식물 성장을 도움), 식초(신맛·음식 맛 조절), 간장(짠맛·간 맞추기), 링거액(수액, 포도당 등이 녹아 있어 병 치료), 스포츠 음료, 유리 세정제 · 용액은 실험실에만 있는 것이 아니라 우리 주변에 많고, 상황과 용도에 맞게 이용함 · 모든 용액을 마셔도 되는 것은 아님',ARRAY['일상생활에서 이용하는 용액을 조사하고 용액의 필요성을 설명(문구 초안 — 성취기준 코드 W7 확인)']::text[],22),
('SC5-1-u3-C23','sci',5,1,'u3',7,'조사·공유 — 용액 그림 카드로 경험 이야기 → 용액 한 가지 고르기 → 스마트 기기로 쓰임새·이용 장소·성질을 중심으로 검색 → 표에 정리 → 공유 플랫폼에 올리기 → 알게 된 점 이야기 · 자료의 출처를 밝힘 · 다른 사람의 얼굴이 드러나는 사진은 허락 없이 쓰지 않음 · 기기에서 냄새나 열이 나면 즉시 중지하고 선생님께 알림',ARRAY['일상생활에서 이용하는 용액을 조사하고 용액의 필요성을 설명(문구 초안 — 성취기준 코드 W7 확인)']::text[],23),
('SC5-1-u3-C24','sci',5,1,'u3',8,'디지털 자료 — 소개할 용액 정하기 → 필요한 상황 토의(용액이 없을 때 불편한 점을 떠올려 필요성과 연관 짓기) → 제작 계획 → 종류(포스터·동영상·카드 뉴스)와 제목 정하기 → 디자인 플랫폼으로 만들기(필요한 내용을 요약) → 누리망·사회 관계망 서비스에 공유 → 필요성 소개 → 다른 모둠 자료에 잘한 점을 바르고 고운 말로 댓글 · 크고 화려하게 꾸미는 것보다 필요성을 옳게 설명하는 것이 중요 · 예: 「비눗물이 사라진다면?」',ARRAY['일상생활에서 이용하는 용액을 조사하고 용액의 필요성을 설명(문구 초안 — 성취기준 코드 W7 확인)']::text[],24),
('SC5-1-u3-C25','sci',5,1,'u3',8,'용액과 직업 — 도시 농업 관리사: 수경 재배에 쓰는 배양액(흙처럼 양분을 공급)을 개발 · 식품 공학 기술자: 녹이는 물질의 종류·순서·물의 온도·용액의 진하기를 확인해 원하는 맛과 영양의 음료를 만듦 · 해양학 연구원: 바다는 여러 물질이 녹아 있는 용액, 바닷물의 온도·염분을 조사해 해양 생태계에 미치는 영향을 분석 · 농업·식품·해양 등 여러 분야에서 용액을 연구',ARRAY['일상생활에서 이용하는 용액을 조사하고 용액의 필요성을 설명(문구 초안 — 성취기준 코드 W7 확인)']::text[],25)
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES 
('SC5-1-u3-X01','sci',5,'u3',ARRAY['SC5-1-u3-C1']::text[],'물에 넣은 물질은 모두 똑같이 변하거나, 어떤 물질도 물에서 변하지 않는다고 여긴다','물질마다 달라요'),
('SC5-1-u3-X02','sci',5,'u3',ARRAY['SC5-1-u3-C2']::text[],'물질의 변신을 촬영하는 차례나 도구의 쓰임을 잘못 안다(물질을 굽거나 얼리기, 막대 없이 넣기, 촬영 뒤에 물질 고르기 등)','고르기 → 묶기 → 넣기 → 찍기 → 편집'),
('SC5-1-u3-X03','sci',5,'u3',ARRAY['SC5-1-u3-C3','SC5-1-u3-C7','SC5-1-u3-C11','SC5-1-u3-C14']::text[],'실험할 때의 안전과 정리를 잘못 안다(물질 맛보기, 보안경 벗기, 남은 물질 아무 데나 버리기 등)','맛보지 않고 정리해요'),
('SC5-1-u3-X04','sci',5,'u3',ARRAY['SC5-1-u3-C4']::text[],'물에 넣은 물질은 무엇이든 다 녹는다고 여긴다','녹지 않는 물질도 있어요'),
('SC5-1-u3-X05','sci',5,'u3',ARRAY['SC5-1-u3-C4','SC5-1-u3-C12']::text[],'녹지 않거나 바닥에 남는 것은 언제나 물이 부족하거나 덜 저었기 때문이라고 여긴다','물질마다 녹는 성질이 달라요'),
('SC5-1-u3-X06','sci',5,'u3',ARRAY['SC5-1-u3-C5']::text[],'용해·용매·용질·용액의 뜻을 서로 바꾸어 안다(용해를 물질로, 용액을 현상으로 등)','현상은 용해, 물질은 용액'),
('SC5-1-u3-X07','sci',5,'u3',ARRAY['SC5-1-u3-C5']::text[],'용매와 용질을 뒤바꾼다(설탕물에서 설탕이 용매, 물이 용질)','녹이는 쪽이 용매'),
('SC5-1-u3-X08','sci',5,'u3',ARRAY['SC5-1-u3-C6']::text[],'물과 섞여 있기만 하면 흙탕물·후춧가루를 넣은 물도 용액이라고 여긴다','녹아 골고루 섞여야 해요'),
('SC5-1-u3-X09','sci',5,'u3',ARRAY['SC5-1-u3-C6']::text[],'용액의 성질을 잘못 안다(부분마다 맛·색이 달라도, 가라앉는 것이 있어도 용액, 색깔이 있으면 용액이 아님 등)','어느 부분이나 같고 가라앉지 않아요'),
('SC5-1-u3-X10','sci',5,'u3',ARRAY['SC5-1-u3-C7']::text[],'세 물질 실험의 조건이나 방법을 잘못 안다(물·물질의 양을 다르게, 약숟가락 하나로 번갈아, 흔들자마자 관찰 등)','같은 양 · 따로 쓰기 · 기다리기'),
('SC5-1-u3-X11','sci',5,'u3',ARRAY['SC5-1-u3-C8','SC5-1-u3-C10']::text[],'물에 녹아 보이지 않게 된 용질은 없어진 것이라고 여긴다','용액 속에 그대로 있어요'),
('SC5-1-u3-X12','sci',5,'u3',ARRAY['SC5-1-u3-C9']::text[],'용질이 용해되면 전체 무게가 줄어들거나 늘어난다고 여긴다','용해 전과 후의 무게는 같아요'),
('SC5-1-u3-X13','sci',5,'u3',ARRAY['SC5-1-u3-C8']::text[],'용질이 용해되는 과정을 잘못 안다(크기 그대로 가라앉음, 점점 커짐, 곧바로 물로 변함 등)','점점 작아지며 골고루 섞여요'),
('SC5-1-u3-X14','sci',5,'u3',ARRAY['SC5-1-u3-C11']::text[],'무게를 비교하는 실험 방법이나 기록을 잘못 안다(접시를 빼고 재기, 결과를 예상에 맞게 고치기 등)','함께 올리고 사실대로 적어요'),
('SC5-1-u3-X15','sci',5,'u3',ARRAY['SC5-1-u3-C9']::text[],'같은 양의 물에 용질을 많이 녹여도 용액의 무게는 같다고 여긴다','녹인 만큼 무거워져요'),
('SC5-1-u3-X16','sci',5,'u3',ARRAY['SC5-1-u3-C12']::text[],'같은 조건의 물에는 모든 용질이 같은 양만큼 녹는다고 여기거나 녹는 양의 차례를 뒤바꾼다','설탕 > 소금 > 백반'),
('SC5-1-u3-X17','sci',5,'u3',ARRAY['SC5-1-u3-C12']::text[],'용질이 바닥에 남은 것은 덜 넣었거나 실험을 잘못했기 때문이고, 오래 저으면 끝없이 녹는다고 여긴다','녹는 양은 용질마다 정해져 있어요'),
('SC5-1-u3-X18','sci',5,'u3',ARRAY['SC5-1-u3-C13']::text[],'공정하게 비교하는 조건을 잘못 안다(물의 양·온도도 함께 바꾸기, 붙임딱지 색처럼 관계없는 것만 맞추기 등)','하나만 다르게, 나머지는 같게'),
('SC5-1-u3-X19','sci',5,'u3',ARRAY['SC5-1-u3-C14']::text[],'실험 도구의 쓰임을 서로 바꾸어 안다(눈금실린더로 젓기, 유리 막대로 물의 양 재기 등)','재는 것 · 젓는 것 · 넣는 것'),
('SC5-1-u3-X20','sci',5,'u3',ARRAY['SC5-1-u3-C14']::text[],'용질이 바닥에 남아도 계속 더 넣거나, 남은 것을 무시하고 다 녹았다고 기록한다','남으면 더 넣지 않아요'),
('SC5-1-u3-X21','sci',5,'u3',ARRAY['SC5-1-u3-C15']::text[],'물의 온도는 용질이 용해되는 양과 관계없다고 여긴다','온도도 요인이에요'),
('SC5-1-u3-X22','sci',5,'u3',ARRAY['SC5-1-u3-C15','SC5-1-u3-C16']::text[],'물의 온도가 낮을수록(차가울수록) 용질이 더 많이 용해된다고 여긴다','따뜻할수록 더 많이'),
('SC5-1-u3-X23','sci',5,'u3',ARRAY['SC5-1-u3-C16']::text[],'바닥에 남은 용질을 녹이려고 용질을 더 넣거나 물을 줄인다','물의 온도를 높여요'),
('SC5-1-u3-X24','sci',5,'u3',ARRAY['SC5-1-u3-C17']::text[],'탐구 계획에서 다르게 해야 할 조건을 잘못 정한다(약숟가락 크기·용질의 종류로 정하기, 여러 개일수록 좋다 등)','알아보려는 것 딱 하나'),
('SC5-1-u3-X25','sci',5,'u3',ARRAY['SC5-1-u3-C18']::text[],'용액의 진하기를 무게·온도·녹인 시간처럼 다른 것으로 안다','같은 용매에 녹은 용질의 양'),
('SC5-1-u3-X26','sci',5,'u3',ARRAY['SC5-1-u3-C19']::text[],'진한 용액과 묽은 용액을 뒤바꾼다(물이 많을수록 진하다, 용질이 적을수록 진하다 등)','용질은 많을수록, 용매는 적을수록 진해요'),
('SC5-1-u3-X27','sci',5,'u3',ARRAY['SC5-1-u3-C20','SC5-1-u3-C21']::text[],'진한 용액과 묽은 용액은 겉으로 어떤 방법으로도 가릴 수 없다고 여긴다','색깔 · 뜨는 정도로 가려요'),
('SC5-1-u3-X28','sci',5,'u3',ARRAY['SC5-1-u3-C21']::text[],'용액이 진할수록 넣은 물체가 더 깊이 가라앉는다고 여긴다','진할수록 높이 떠요'),
('SC5-1-u3-X29','sci',5,'u3',ARRAY['SC5-1-u3-C20','SC5-1-u3-C21']::text[],'진하기를 비교하는 방법을 잘못 안다(맛보기, 크기·무게가 다른 방울토마토, 녹인 시간이나 비커 크기 견주기 등)','같은 물체 · 흰 종이'),
('SC5-1-u3-X30','sci',5,'u3',ARRAY['SC5-1-u3-C20']::text[],'백설탕 용액처럼 색깔이 거의 없는 용액도 색깔만 보고 진하기를 쉽게 가릴 수 있다고 여긴다','색이 거의 같아요'),
('SC5-1-u3-X31','sci',5,'u3',ARRAY['SC5-1-u3-C21']::text[],'떠 있는 물체를 낮추려고 용질을 더 넣거나, 높이려고 물을 더 넣는다','물을 더 넣으면 묽어져요'),
('SC5-1-u3-X32','sci',5,'u3',ARRAY['SC5-1-u3-C22']::text[],'용액은 과학실에서만 볼 수 있다고 여긴다','우리 주변에 많아요'),
('SC5-1-u3-X33','sci',5,'u3',ARRAY['SC5-1-u3-C22']::text[],'생활 속 용액과 그 쓰임을 잘못 짝짓는다(손 소독제로 간 맞추기, 식초로 세균 없애기 등)','상황과 용도에 맞게'),
('SC5-1-u3-X34','sci',5,'u3',ARRAY['SC5-1-u3-C22','SC5-1-u3-C23']::text[],'모든 용액은 마시거나 맛보아도 된다고 여긴다','마시면 안 되는 용액이 많아요'),
('SC5-1-u3-X35','sci',5,'u3',ARRAY['SC5-1-u3-C23']::text[],'조사하고 공유하는 방법이나 태도를 잘못 안다(출처 빼기, 베끼기, 얼굴 사진 허락 없이 올리기, 기기에서 열이 나도 계속 쓰기 등)','출처 · 허락 · 안전'),
('SC5-1-u3-X36','sci',5,'u3',ARRAY['SC5-1-u3-C24']::text[],'디지털 자료는 크고 화려하게 꾸밀수록 좋은 자료라고 여긴다','필요성을 옳게 설명했나요?'),
('SC5-1-u3-X37','sci',5,'u3',ARRAY['SC5-1-u3-C24']::text[],'자료에 용액의 필요성 대신 이름만 쓰거나 관계없는 내용(값·포장 색·위험만 등)을 담는다','없을 때의 불편함'),
('SC5-1-u3-X38','sci',5,'u3',ARRAY['SC5-1-u3-C24']::text[],'다른 모둠 자료에 비방하거나 불쾌하게 하는 댓글을 단다','바르고 고운 말'),
('SC5-1-u3-X39','sci',5,'u3',ARRAY['SC5-1-u3-C24']::text[],'디지털 자료를 만들고 나누는 차례를 잘못 안다(용액도 정하지 않고 공유부터, 댓글부터 등)','계획 → 만들기 → 나누기'),
('SC5-1-u3-X40','sci',5,'u3',ARRAY['SC5-1-u3-C25']::text[],'용액을 연구하는 직업과 하는 일을 잘못 짝짓거나, 바닷물은 용액이 아니라고 여긴다','배양액 · 음료 · 바닷물'),
('SC5-1-u3-X41','sci',5,'u3',ARRAY['SC5-1-u3-C25']::text[],'용액을 연구하는 일은 과학자만 할 수 있거나 우리 생활과 관계없다고 여긴다','여러 분야에서 연구해요')
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES 
('g5_1_sci_u3_L01_basic#1','sci',5,1,'u3','L01','g5_1_sci_u3_L01_basic','lesson_basic','SC5-1-u3-C2',1,'mc','auto','고른 물질을 물에 넣기 전에 무엇을 하나요?',ARRAY['SC5-1-u3-X02']::text[],false,'{"seq":1,"concept":"SC5-1-u3-C2","difficulty":1,"kind":"mc","stem":"고른 물질을 물에 넣기 전에 무엇을 하나요?","options":[{"t":"빵 끈으로 묶어 나무 막대에 연결한다","correct":true},{"t":"불에 살짝 구워 둔다","mis":"SC5-1-u3-X02"},{"t":"잘게 부수어 가루로 만든다","mis":"SC5-1-u3-X02"},{"t":"얼음처럼 차갑게 얼린다","mis":"SC5-1-u3-X02"}],"explanation":["준비물을 떠올려요.","빵 끈과 나무 막대예요.","묶어서 막대에 연결해요."]}'::jsonb),
('g5_1_sci_u3_L01_basic#2','sci',5,1,'u3','L01','g5_1_sci_u3_L01_basic','lesson_basic','SC5-1-u3-C3',1,'ox','auto','실험에 사용하는 물질은 맛보지 않아요.',ARRAY['SC5-1-u3-X03']::text[],false,'{"seq":2,"concept":"SC5-1-u3-C3","difficulty":1,"kind":"ox","stem":"실험에 사용하는 물질은 맛보지 않아요.","answer":"O","reason_options":[{"t":"어떤 물질인지 모르고 맛보면 몸에 해로울 수 있기 때문에","correct":true},{"t":"맛을 보면 물질이 변하는 모습이 더 잘 보이기 때문에","mis":"SC5-1-u3-X03"}],"mis":"SC5-1-u3-X03","explanation":["안전을 떠올려요.","몸에 해로울 수 있어요.","맞는 말이에요."]}'::jsonb),
('g5_1_sci_u3_L01_basic#3','sci',5,1,'u3','L01','g5_1_sci_u3_L01_basic','lesson_basic','SC5-1-u3-C2',1,'sa','auto','「물질이 변하는 모습을 스마트 기기로 □□□으로 촬영합니다.」 □□□에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SC5-1-u3-C2","difficulty":1,"kind":"sa","stem":"「물질이 변하는 모습을 스마트 기기로 □□□으로 촬영합니다.」 □□□에 알맞은 말을 쓰세요.","answer":["동영상"],"explanation":["움직이는 모습을 남겨요.","세 글자예요.","동영상이에요."],"mis":"SC5-1-u3-X02"}'::jsonb),
('g5_1_sci_u3_L01_basic#4','sci',5,1,'u3','L01','g5_1_sci_u3_L01_basic','lesson_basic','SC5-1-u3-C1',1,'mc','auto','거품 목욕제를 물에 넣으면 어떻게 되나요?',ARRAY['SC5-1-u3-X01']::text[],false,'{"seq":4,"concept":"SC5-1-u3-C1","difficulty":1,"kind":"mc","stem":"거품 목욕제를 물에 넣으면 어떻게 되나요?","options":[{"t":"거품을 내며 녹는다","correct":true},{"t":"아무 변화가 없다","mis":"SC5-1-u3-X01"},{"t":"더 단단해진다","mis":"SC5-1-u3-X01"},{"t":"물이 모두 사라진다","mis":"SC5-1-u3-X01"}],"explanation":["목욕할 때를 떠올려요.","거품이 나요.","거품을 내며 녹아요."]}'::jsonb),
('g5_1_sci_u3_L01_basic#5','sci',5,1,'u3','L01','g5_1_sci_u3_L01_basic','lesson_basic','SC5-1-u3-C2',2,'match','auto','물질의 변신 촬영에 쓰는 준비물과 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC5-1-u3-C2","difficulty":2,"kind":"match","stem":"물질의 변신 촬영에 쓰는 준비물과 하는 일을 알맞게 이으세요.","pairs":[{"l":"빵 끈","r":"고른 물질을 묶는다"},{"l":"나무 막대","r":"빵 끈을 연결해 손으로 잡는다"},{"l":"물이 담긴 비커","r":"물질을 넣는 곳이다"},{"l":"스마트 기기","r":"변하는 모습을 촬영한다"}],"mis":"SC5-1-u3-X02","explanation":["하나씩 떠올려요.","묶고, 잡고, 넣고, 찍어요.","네 가지가 달라요."]}'::jsonb),
('g5_1_sci_u3_L01_basic#6','sci',5,1,'u3','L01','g5_1_sci_u3_L01_basic','lesson_basic','SC5-1-u3-C3',2,'mc','auto','실험이 끝난 뒤 하는 일로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u3-X03']::text[],false,'{"seq":6,"concept":"SC5-1-u3-C3","difficulty":2,"kind":"mc","stem":"실험이 끝난 뒤 하는 일로 알맞은 것은 어느 것인가요?","options":[{"t":"주변을 깨끗이 정리하고 폐기물을 올바르게 처리한다","correct":true},{"t":"남은 물질을 아무 데나 버린다","mis":"SC5-1-u3-X03"},{"t":"비커를 그대로 두고 자리를 떠난다","mis":"SC5-1-u3-X03"},{"t":"남은 물질을 맛본다","mis":"SC5-1-u3-X03"}],"explanation":["끝난 뒤를 떠올려요.","깨끗이 정리해요.","첫 번째예요."]}'::jsonb),
